// patch.mjs - fixes number reading + English/Tagalog word detection in the Act 8 Mini-Bot.
// Usage (from the project root, the folder that contains app.py):   node patch.mjs
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";

if (!fs.existsSync("app.py") || !fs.existsSync("minibot")) {
  console.error("Run this from the project root (the folder containing app.py and minibot/).");
  process.exit(1);
}

const FILES = {
 "minibot/langdetect.py": "",
 "minibot/textnorm.py": "",
 "tests/test_core.py": "",
 "data/en_words.txt": "",
 "data/tl_words.txt": ""
};

for (const [rel, b64] of Object.entries(FILES)) {
  const data = zlib.gunzipSync(Buffer.from(b64, "base64"));
  fs.mkdirSync(path.dirname(rel), { recursive: true });
  if (fs.existsSync(rel) && !fs.existsSync(rel + ".bak")) fs.copyFileSync(rel, rel + ".bak");
  fs.writeFileSync(rel, data);
  console.log("patched  " + rel + "  (" + data.length + " bytes)");
}
console.log("\nDone. Restart the app (Ctrl+C, then: python app.py) and try the sentence again.");
console.log("Old versions were saved as *.bak - delete them or add *.bak to .gitignore.");
